using System;using System.IO;using System.Collections.Generic;using UnityEngine;
[Serializable] public class CatalogItem {public string id,title,animation,source,target_file,generated_parts_file,source_parts_file,source_parts_mode,source_parts_sha256,diagram_file,diagram_sha256;public float width,height,display_scale,center_x,center_y;public bool textured;}
[Serializable] public class CatalogManifest {public CatalogItem[] items;}
[Serializable] public class SpriteObject {public float[] center,topLeft;public bool @static;}
[Serializable] public class SpriteScene {public float width,height,slope_radians;public SpriteObject[] objects;}
// Explicit authored animation adapter, NOT inferred rigging or generated physics.
public class CatalogScene:MonoBehaviour {
 SourceDiagramPhysics diagram;SourcePartsScene sourceParts;SourceMathScene sourceMath;CatalogGeneratedParts generatedParts;float nextMathLog;
 public CatalogItem item; public bool trackingAvailable=true;public bool playing=true;public float parameter=.5f,time;public int stage;Transform body;List<Transform> parts=new List<Transform>();SpriteScene sprites;float theta=-.476f,omega,cartPosition,cartVelocity;bool springAttached;LineRenderer graph;TextMesh label;List<Vector3> trace=new List<Vector3>();
 public void Configure(CatalogItem selected){item=selected;transform.localPosition=new Vector3(item.center_x,item.center_y,0);body=new GameObject("Inferred mesh (unrigged)").transform;body.SetParent(transform,false);
 if(!string.IsNullOrEmpty(item.diagram_file)){diagram=gameObject.AddComponent<SourceDiagramPhysics>();diagram.Configure(item);return;}
 if(item.animation=="source-parts"){sourceParts=gameObject.AddComponent<SourcePartsScene>();sourceParts.Configure(item);return;}
 if(item.animation.StartsWith("math-")){sourceMath=gameObject.AddComponent<SourceMathScene>();sourceMath.Configure(item);return;}
 if(item.animation.StartsWith("physics")){LoadSprites();if(item.animation=="physics-pendulum")graph=Line("Measured solver angle-time",Color.cyan);else graph=Line("Authored Hooke spring constraint",Color.yellow);}
 else if(item.animation=="math"){graph=Line("Equation-linked graph",Color.cyan);}
 else {LoadMesh();CreateParts();}
 var go=new GameObject("Parameter and provenance");go.transform.SetParent(transform,false);label=go.AddComponent<TextMesh>();label.characterSize=.0025f;label.fontSize=38;label.anchor=TextAnchor.MiddleCenter;label.alignment=TextAlignment.Center;go.transform.localPosition=new Vector3(0,-item.height*.53f,-.012f);Reset();}
 void LoadMesh(){var a=Resources.Load<TextAsset>("Catalog/"+item.id);if(!a)throw new Exception("Missing inferred mesh "+item.id);using(var r=new BinaryReader(new MemoryStream(a.bytes))){int n=r.ReadInt32(),f=r.ReadInt32();var v=new Vector3[n];var c=new Color32[n];var ix=new int[f*3];for(int i=0;i<n;i++)v[i]=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());for(int i=0;i<n;i++)c[i]=new Color32(r.ReadByte(),r.ReadByte(),r.ReadByte(),r.ReadByte());for(int i=0;i<ix.Length;i++)ix[i]=r.ReadInt32();var m=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};m.vertices=v;m.colors32=c;m.triangles=ix;if(item.textured){var uv=new Vector2[n];for(int i=0;i<n;i++)uv[i]=new Vector2(r.ReadSingle(),r.ReadSingle());m.uv=uv;}m.RecalculateNormals();m.RecalculateBounds();body.gameObject.AddComponent<MeshFilter>().sharedMesh=m;var renderer=body.gameObject.AddComponent<MeshRenderer>();renderer.sharedMaterial=Resources.Load<Material>("vertex-color");if(item.textured){renderer.sharedMaterial=new Material(Resources.Load<Shader>("CatalogSurface"));renderer.sharedMaterial.SetTexture("_BaseMap",Resources.Load<Texture2D>("Catalog/"+item.id+"-texture"));}}}
 Transform Part(PrimitiveType kind,Color color){var g=GameObject.CreatePrimitive(kind);Destroy(g.GetComponent<Collider>());g.transform.SetParent(transform,false);var mat=new Material(Resources.Load<Shader>("CatalogSurface"));mat.SetColor("_BaseColor",color);g.GetComponent<Renderer>().material=mat;parts.Add(g.transform);return g.transform;}
 void CreateParts(){string a=item.animation;
 if(!string.IsNullOrEmpty(item.generated_parts_file)){generatedParts=gameObject.AddComponent<CatalogGeneratedParts>();generatedParts.Configure(item.generated_parts_file);return;}

 if(a=="drive")return; // Inferred rigid car already contains wheels: do not cover it with coloured stand-ins.
int count=a=="orbit"?4:(a=="explode"||a=="bond"||a=="unzip")?6:(a=="count"||a=="divide")?10:(a=="flow"||a=="cycle"||a=="pulse"||a=="release")?8:(a=="load"||a=="field")?5:(a=="drive"||a=="walk"||a=="swim")?4:(a=="fold"||a=="flap"||a=="gears"||a=="spin")?2:0;for(int i=0;i<count;i++)Part((a=="fold"||a=="flap"||a=="count"||a=="divide")?PrimitiveType.Cube:(a=="gears"||a=="spin"||a=="drive"||a=="walk")?PrimitiveType.Cylinder:PrimitiveType.Sphere,Color.HSVToRGB((i*.17f)%1,.65f,.95f));}
 LineRenderer Line(string name,Color color){var g=new GameObject(name);g.transform.SetParent(transform,false);var l=g.AddComponent<LineRenderer>();l.useWorldSpace=false;l.widthMultiplier=.001f;l.material=new Material(Shader.Find("Sprites/Default"));l.startColor=l.endColor=color;return l;}
 void LoadSprites(){sprites=JsonUtility.FromJson<SpriteScene>(Resources.Load<TextAsset>("Catalog/"+item.id).text);var repair=Resources.Load<Texture2D>("Catalog/"+item.id+"-repair");if(repair){var patch=new GameObject("Original inpainted pixels under dynamic alpha only");patch.transform.SetParent(transform,false);patch.transform.localPosition=new Vector3(0,0,-.009f);var sr=patch.AddComponent<SpriteRenderer>();sr.sprite=Sprite.Create(repair,new Rect(0,0,repair.width,repair.height),Vector2.one*.5f,sprites.width/item.width);}for(int i=0;i<sprites.objects.Length;i++){var tex=Resources.Load<Texture2D>("Catalog/"+item.id+"-"+i);var o=sprites.objects[i];var g=new GameObject("Original segmented sprite "+i);g.transform.SetParent(transform,false);var sr=g.AddComponent<SpriteRenderer>();sr.sprite=Sprite.Create(tex,new Rect(0,0,tex.width,tex.height),new Vector2((o.center[0]-o.topLeft[0])/tex.width,1-(o.center[1]-o.topLeft[1])/tex.height),sprites.width/item.width);parts.Add(g.transform);g.transform.localPosition=Pixel(o.center[0],o.center[1]);}}
 Vector3 Pixel(float x,float y){return new Vector3((x/sprites.width-.5f)*item.width,(.5f-y/sprites.height)*item.height,-.012f);}
 public void SetTrackingAvailable(bool available){trackingAvailable=available;if(diagram)diagram.enabled=available;if(sourceParts)sourceParts.enabled=available;if(sourceMath)sourceMath.enabled=available;}
 public void Tap(){if(!trackingAvailable)return;if(diagram){diagram.Tap();return;}if(sourceParts){sourceParts.playing=!sourceParts.playing;return;}if(sourceMath){sourceMath.binding.selected=!sourceMath.binding.selected;Debug.Log("CATALOG actual OVR select id="+item.id);return;}playing=!playing;stage=(stage+1)%3;Debug.Log("CATALOG actual OVR input toggle id="+item.id+" stage="+stage);}
 public void Reset(){if(!trackingAvailable)return;if(diagram){diagram.Reset();diagram.Render();return;}if(sourceParts){sourceParts.Reset();sourceParts.Sample();return;}if(sourceMath){sourceMath.binding.Reset();sourceMath.Render();return;}playing=false;parameter=.5f;time=0;stage=0;theta=-.476f;omega=cartPosition=cartVelocity=0;springAttached=false;trace.Clear();if(graph)graph.positionCount=0;}
 public void Spring(){if(!trackingAvailable)return;if(diagram){diagram.Compare();return;}if(sourceParts){sourceParts.ToggleMode();return;}if(item.animation!="physics-incline")return;springAttached=!springAttached;cartVelocity=.15f;Debug.Log("CATALOG actual OVR spring="+springAttached);}
 public void ControlAxes(Vector2 left,Vector2 right,float dt,string inputSource="OVRInput"){if(!trackingAvailable)return;if(diagram){diagram.Axes(left,right,dt);return;}if(sourceParts){sourceParts.Axes(left,right,dt);return;}if(sourceMath){sourceMath.binding.Axes(left,right,dt);if((left.sqrMagnitude>.01f||right.sqrMagnitude>.01f)&&Time.realtimeSinceStartup>nextMathLog){nextMathLog=Time.realtimeSinceStartup+.5f;Debug.Log("CATALOG math axis source="+inputSource+" id="+item.id+" state="+sourceMath.binding.Equation);}return;}Parameter(right.x*dt*.5f);}
 public void Parameter(float delta){if(!trackingAvailable)return;parameter=Mathf.Clamp01(parameter+delta);}
 void Update(){if(!trackingAvailable)return;if(sourceMath||sourceParts||diagram)return;float dt=Mathf.Min(Time.deltaTime,.05f);if(playing)time+=dt;float p=parameter,t=time,s=Mathf.Sin(t*(.5f+3*p));string a=item.animation;
 label.text=item.title+"\nA: play/pause  B: reset  X/Y: scene  stick: parameter "+p.ToString("F2")+"\n"+(a.StartsWith("physics")?"Original cutouts · Unity numerical solver":a=="math"?"Original page · newly authored equation binding":(item.textured?"Hunyuan UV mesh + authored mechanics":"TripoSR mesh + authored mechanics; not learned rigging"));
 if(a=="math"){float coefficient=.2f+2.8f*p;label.text+="\ny = "+coefficient.ToString("F2")+" x² · graph/equation linked";graph.positionCount=81;for(int i=0;i<81;i++){float x=(i-40)/40f;graph.SetPosition(i,new Vector3(x*.085f,(coefficient*x*x-1)*.028f,-.012f));}return;}
 if(a=="physics-pendulum"){var fixedPart=sprites.objects[0].center;var bob=sprites.objects[1].center;float length=Vector2.Distance(new Vector2(fixedPart[0],fixedPart[1]),new Vector2(bob[0],bob[1]));if(playing){for(int k=0;k<8;k++){float h=dt/8;omega+=(-(.5f+p*1.5f)*9.81f/(length*item.width/sprites.width)*Mathf.Sin(theta)-.04f*omega)*h;theta+=omega*h;}trace.Add(new Vector3(-.09f+(time%12)*.015f,-item.height*.38f+theta*.02f,-.018f));if(trace.Count>360)trace.RemoveAt(0);}parts[1].localPosition=Pixel(fixedPart[0]+Mathf.Sin(theta)*length,fixedPart[1]+Mathf.Cos(theta)*length);graph.positionCount=trace.Count;graph.SetPositions(trace.ToArray());label.text+="\nθ="+theta.ToString("F2")+" rad · g="+((.5f+1.5f*p)*9.81f).ToString("F1");return;}
 if(a=="physics-incline"){float slope=sprites.slope_radians,mu=p*.15f;float end=(787-sprites.objects[0].center[0])*item.width/sprites.width;if(playing){float acceleration=9.81f*(Mathf.Sin(slope)-mu*Mathf.Cos(slope)*(cartVelocity<0?-1:1));if(springAttached)acceleration-=(10+90*p)/5*cartPosition+.15f*cartVelocity;cartVelocity+=acceleration*dt;cartPosition=Mathf.Clamp(cartPosition+cartVelocity*dt,0,end);if(cartPosition>=end||cartPosition<=0)cartVelocity=0;}parts[0].localPosition=Pixel(sprites.objects[0].center[0],sprites.objects[0].center[1])+new Vector3(cartPosition,-cartPosition*Mathf.Tan(slope),0);graph.positionCount=springAttached?18:0;if(springAttached){var origin=Pixel(sprites.objects[0].center[0]-113,sprites.objects[0].center[1]-113*Mathf.Tan(slope));var endPoint=parts[0].localPosition;for(int i=0;i<18;i++){var point=Vector3.Lerp(origin,endPoint,i/17f);if(i>0&&i<17)point.y+=(i%2==0?1:-1)*.002f;graph.SetPosition(i,point);}}label.text+="\nL-stick click: attach/remove Hooke spring · k="+(10+90*p).ToString("F1")+" N/m (new Unity solver)";label.text+="\ncart v="+cartVelocity.ToString("F2")+"m/s · μ="+mu.ToString("F2");return;}
 body.localPosition=new Vector3(0,0,-.06f);body.localRotation=Quaternion.identity;body.localScale=Vector3.one*(item.display_scale>0?item.display_scale:.1f);
 if(a=="orbit")body.localRotation=Quaternion.Euler(0,0,t*12);
 if(a=="drive"||a=="walk"||a=="swim"){body.localPosition+=new Vector3(Mathf.Sin(t*(.5f+2*p))*.07f,0,0);body.localRotation=Quaternion.Euler(0,(p-.5f)*90,0);}
 if(a=="grow"||a=="expand")body.localScale*=.2f+p*.8f;
 if(a=="breathe"||a=="pulse")body.localScale*=1+.15f*s;
 if(a=="swing"||a=="tilt")body.localRotation=Quaternion.Euler(0,0,(a=="swing"?s*p*.55f:(p-.5f)*.8f)*Mathf.Rad2Deg);
 if(a=="lift"||a=="reciprocate")body.localPosition+=new Vector3(0,0,-(a=="lift"?p*.06f:s*.028f));
 if(a=="story"){body.localPosition+=new Vector3((stage-1)*.04f,0,-stage*.035f);body.localRotation=Quaternion.Euler(0,stage*35,0);}
 if(a=="explode"||a=="bond"||a=="unzip")body.localScale*=1+p*.25f;
 if(generatedParts){generatedParts.Sample(t,p);body.gameObject.SetActive(false);return;}
 for(int i=0;i<parts.Count;i++){var q=parts[i];q.localRotation=Quaternion.identity;q.localScale=Vector3.one*.008f;q.localPosition=new Vector3(0,0,-.09f);
 if(a=="orbit"){float ph=t*(.3f+2*p)/(i+1)+i*1.5f,r=.045f+i*.019f;q.localPosition+=new Vector3(Mathf.Cos(ph)*r,Mathf.Sin(ph)*r,0);q.localScale=Vector3.one*(.016f+i*.004f);}
 else if(a=="explode"||a=="bond"||a=="unzip"){float ph=i*Mathf.PI/3,r=.025f+p*.065f;q.localPosition+=new Vector3(Mathf.Cos(ph)*r,Mathf.Sin(ph)*r,-p*.03f);q.localScale=Vector3.one*.016f;}
 else if(a=="gears"||a=="spin"){q.localPosition+=new Vector3(i==0?-.03f:.03f,0,0);q.localScale=new Vector3(.056f,.006f,.056f);q.localRotation=Quaternion.Euler(90,(i==0?1:-1)*t*(1+6*p)*Mathf.Rad2Deg,0);}
 else if(a=="fold"||a=="flap"){q.localPosition+=new Vector3(i==0?-.025f:.025f,0,0);q.localScale=new Vector3(.048f,.055f,.001f);q.localRotation=Quaternion.Euler(0,(i==0?-1:1)*(p*90+(a=="flap"?s*17:0)),0);}
 else if(a=="count"||a=="divide"){q.localPosition+=new Vector3((i%5-2)*(.018f+.012f*p),(i/5)*.018f,-p*.025f);q.localScale=Vector3.one*.012f;}
 else if(a=="flow"||a=="cycle"||a=="pulse"||a=="release"){float v=(t*(.15f+p*.4f)+i/8f)%1;q.localPosition+=new Vector3((v-.5f)*.14f,a=="cycle"?Mathf.Sin(v*Mathf.PI*2)*.025f:0,0);}
 else if(a=="load"||a=="field"){q.localPosition+=new Vector3((i-2)*.025f,0,-p*.03f);q.localScale=new Vector3(.004f,.004f,.03f);}
 else if(a=="drive"||a=="walk"||a=="swim"){q.localPosition=body.localPosition+new Vector3(i<2?-.045f:.045f,i%2==0?-.026f:.026f,0);q.localScale=new Vector3(.024f,.005f,.024f);q.localRotation=Quaternion.Euler(t*(1+5*p)*Mathf.Rad2Deg,0,90);}
 }
 }
 void DisposeOwned(UnityEngine.Object owned){if(Application.isPlaying)Destroy(owned);else DestroyImmediate(owned);}
 void OnDestroy(){if(body){var f=body.GetComponent<MeshFilter>();if(f&&f.sharedMesh)DisposeOwned(f.sharedMesh);if(item.textured){var r=body.GetComponent<Renderer>();if(r)DisposeOwned(r.sharedMaterial);}}foreach(var part in parts){var sr=part?part.GetComponent<SpriteRenderer>():null;if(sr&&sr.sprite)DisposeOwned(sr.sprite);if(part&&!sr){var r=part.GetComponent<Renderer>();if(r)DisposeOwned(r.sharedMaterial);}}if(graph)DisposeOwned(graph.sharedMaterial);}

}
